// 리라아트고등학교 (서울 중구) - automatic high-school package (auto-school track, user decision 2026-10-23). Generated by scripts/campuses/liraart/build-package.mjs
// from OSM way/464461379 + AWS Terrain Tiles: every school building destructible (grammar models, floors estimated where OSM has none),
// a baked ground (one terrain mesh with two drawn colour maps), fence / gates / stands / goals, trees and the extruded neighbourhood fading
// into the haze. Local only (registry public: false). Do not edit by hand - rerun the generator.
import { WORLD_UNITS_PER_METER, GEO_ORIGIN, LIRAART_PLACEMENTS, LIRAART_BUILDING_BASE, LIRAART_HEIGHT_GRIDS, LIRAART_HEIGHT_RANGE_M, LIRAART_ENV_IDS, LIRAART_DISPLAY, LIRAART_START_FRAME, LIRAART_OVERVIEW_AZIMUTH, LIRAART_CAMERA, LIRAART_PROVENANCE } from './data.js';
import { LIRAART_FOOTPRINTS } from './footprints.js';
import { LIRAART_PROTECTED } from './protected.js';

const MODEL_IDS = Object.freeze(LIRAART_PLACEMENTS.map(p => p.id));
const asset = file => new URL(`../../../assets/campuses/liraart/${file}`, import.meta.url).href;
const HAZE = LIRAART_DISPLAY.haze, FADE = LIRAART_DISPLAY.fade;

export const LIRAART = Object.freeze({
  id: 'liraart',
  meta: Object.freeze({ school: '리라아트고등학교', campus: '서울 중구', short: '리라아트고', modelNoun: '리라아트고' }),
  geo: Object.freeze({ origin: GEO_ORIGIN, worldUnitsPerMeter: WORLD_UNITS_PER_METER }),
  placements: LIRAART_PLACEMENTS,
  approvedCount: LIRAART_PLACEMENTS.length,
  additionalCount: 0,
  coreIds: MODEL_IDS,
  startBuildingId: MODEL_IDS[0],
  // camera picked by scripts/auto-school/build.mjs from the measured occlusion (azimuths in radians, elevations in degrees, src/camera.js angles)
  view: Object.freeze({ startFrame: LIRAART_START_FRAME, overviewAzimuth: LIRAART_OVERVIEW_AZIMUTH }),
  camera: LIRAART_CAMERA,
  models: Object.freeze({
    manifests: Object.freeze([
      Object.freeze({ url: asset('manifest.json'), expectedIds: MODEL_IDS }),
      Object.freeze({ url: asset('environment.json'), expectedIds: LIRAART_ENV_IDS }),
    ]),
    proceduralIds: Object.freeze([]),
    createProceduralSource: () => { throw new Error('No procedural buildings in this campus'); },
    enhanceFacade: () => ({ stats: {}, dispose() {} }),
  }),
  terrain: Object.freeze({ heightGrids: LIRAART_HEIGHT_GRIDS, buildingBase: LIRAART_BUILDING_BASE, source: LIRAART_PROVENANCE.terrain }),
  environment: Object.freeze({ provenance: LIRAART_PROVENANCE, sourceNote: 'OSM ground surfaces and surroundings (© OpenStreetMap contributors, ODbL); heights, floors and planting estimated automatically' }),
  ground: Object.freeze({
    baked: Object.freeze({ envIds: LIRAART_ENV_IDS, castShadow: Object.freeze([]),
      // 11-10 3차 검수 LIRA-31: 완파 뒤 땅 고르기가 윤곽 밖 4 m 띠의 소품(담장·서쪽 마당 단)까지 끌어내려 담장이 꺼지고 글자만 떴다 → 본관은 윤곽 안쪽만 고른다
      flat: Object.freeze({ byId: Object.freeze({ main: Object.freeze({ band_m: 0 }) }) }),
      fade: Object.freeze({ centre_m: Object.freeze([...FADE.centreEN]), near_m: FADE.r0_m, far_m: FADE.r1_m, linear: FADE.linearShare, colour: HAZE }), playMargin_m: 30,
      source: 'scripts/campuses/liraart/build-package.mjs baked ground' }),
  }),
  protected: Object.freeze({ models: LIRAART_PROTECTED }),
  hazardTape: Object.freeze({ footprints: LIRAART_FOOTPRINTS }),
  scene: Object.freeze({
    background: HAZE, fog: Object.freeze({ color: HAZE, near: 500, far: 1400 }),
    hemisphere: Object.freeze({ sky: '#ffffff', ground: '#7d8a78', intensity: 1.35 }),
    sun: Object.freeze({ color: '#fff4e2', intensity: 3.1, position: Object.freeze([-110, 165, 140]), shadowSpan: 200 }),
    floor: Object.freeze({ color: '#c9cbc8', hidden: true, y: LIRAART_HEIGHT_RANGE_M[0] * WORLD_UNITS_PER_METER - .3 }),
  }),
});
